import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
dayjs.extend(utc);
export const fetchAnalysisData = async (startDate, endDate, epochLength, numSurfers, numAnchors, analysisType) => {
   
    // Construct API URL dynamically
    const API_URL = `https://secret-waters-68356-86a3d5e5f97f.herokuapp.com/?start=${startDate.toISOString()}&end=${endDate.toISOString()}&epoch=${epochLength}&surfers=${numSurfers}&anchors=${numAnchors}&points=10`;
    
    try {
        console.log(`📡 Fetching data for ${analysisType} from:`, API_URL);

        const response = await fetch(API_URL);
        if (!response.ok) {
            throw new Error(`HTTP error! Status: ${response.status}`);
        }

        const responseData = await response.json();
        console.log("✅ Raw API Response:", responseData);

        // Validate response format
        if (!responseData || !responseData.data || !Array.isArray(responseData.data)) {
            console.error("❌ Unexpected API response format", responseData);
            return { points: [], series: [] };
        }

        // Extract timestamps
        const points = responseData.data.map((entry) => {
            const date = new Date(entry.Timestamp);
            return isNaN(date) ? null : date.toISOString();
        }).filter(Boolean);

        // Select data based on `analysisType`
        let series = [];
        switch (analysisType) {
            case "Pool Composition":
                series = [
                    { name: "Anchor Liquidity", data: responseData.data.map((entry) => parseFloat(entry.AnchorLiq) || 0) },
                    { name: "Anchor Value", data: responseData.data.map((entry) => parseFloat(entry.AnchorValue) || 0) },
                    { name: "Anchor Value Regular", data: responseData.data.map((entry) => parseFloat(entry.AnchorValueRegular) || 0) },
                    { name: "Surfer Liquidity", data: responseData.data.map((entry) => parseFloat(entry.SurferLiq) || 0) },
                    { name: "Surfer Value", data: responseData.data.map((entry) => parseFloat(entry.SurferValue) || 0) },
                    { name: "Surfer Value Regular", data: responseData.data.map((entry) => parseFloat(entry.SurferValueRegular) || 0) },
                    { name: "Total Profits", data: responseData.data.map((entry) => parseFloat(entry.TotalProfits) || 0) },
                    { name: "Total Loss", data: responseData.data.map((entry) => parseFloat(entry.TotalLoss) || 0) },
                    { name: "Price", data: responseData.data.map((entry) => parseFloat(entry.Price) || 0) },
                    { name: "Entry Price", data: responseData.data.map((entry) => parseFloat(entry.EntryPrice) || 0) },
                    { name: "Min Price", data: responseData.data.map((entry) => parseFloat(entry.MinPrice) || 0) }
                ];
                break;

            case "Compare":
                series = [
                    { name: "Price", data: responseData.data.map((entry) => parseFloat(entry.Price) || 0) },
                    { name: "Anchor Value", data: responseData.data.map((entry) => parseFloat(entry.AnchorValue) || 0) },
                    { name: "Anchor Value Regular", data: responseData.data.map((entry) => parseFloat(entry.AnchorValueRegular) || 0) },
                    { name: "Surfer Value", data: responseData.data.map((entry) => parseFloat(entry.SurferValue) || 0) },
                    { name: "Surfer Value Regular", data: responseData.data.map((entry) => parseFloat(entry.SurferValueRegular) || 0) }
                ];
                break;

            case "Surfer Token Price":
                series = [
                    { name: "Surfer Token Price", data: responseData.data.map((entry) => parseFloat(entry.SurferTokenPrice) || 0) },
                    { name: "Anchor Token Price", data: responseData.data.map((entry) => parseFloat(entry.AnchorTokenPrice) || 0) },
                    { name: "Price", data: responseData.data.map((entry) => parseFloat(entry.Price) || 0) },
                    { name: "Min Price", data: responseData.data.map((entry) => parseFloat(entry.MinPrice) || 0) },
                    { name: "Entry Price", data: responseData.data.map((entry) => parseFloat(entry.EntryPrice) || 0) }
                ];
                break;

            case "Surfer vs Anchor":
                series = [
                    { name: "Anchor Liquidity", data: responseData.data.map((entry) => parseFloat(entry.AnchorLiq) || 0) },
                    { name: "Surfer Liquidity", data: responseData.data.map((entry) => parseFloat(entry.SurferLiq) || 0) },
                    { name: "Price", data: responseData.data.map((entry) => parseFloat(entry.Price) || 0) }
                ];
                break;

            case "Profits and Losses":
                series = [
                    { name: "Total Loss", data: responseData.data.map((entry) => parseFloat(entry.TotalLoss) || 0) },
                    { name: "Total Profits", data: responseData.data.map((entry) => parseFloat(entry.TotalProfits) || 0) },
                    { name: "Price", data: responseData.data.map((entry) => parseFloat(entry.Price) || 0) },
                    { name: "Entry Price", data: responseData.data.map((entry) => parseFloat(entry.EntryPrice) || 0) }
                ];
                break;

            default:
                console.error("❌ Invalid analysis type:", analysisType);
                return { points: [], series: [] };
        }

        let actions = [
            { name: "Action", data: responseData.actions.map((entry) => entry.Action || "") },
            { name: "User", data: responseData.actions.map((entry) => entry.User || "") },
            { name: "Amount", data: responseData.actions.map((entry) => parseFloat(entry.Amount) || 0) },
            { 
                name: "Timestamp", 
                data: responseData.actions.map((entry) => {
                    let timestamp = entry.EntryAt || entry.SwitchedAt || entry.ExitAt;
                    return timestamp ? new Date(timestamp).toISOString() : null;
                })
            }
        ];


        console.log(`✅ Parsed API Data for ${analysisType}:`, { points, series , actions});
        return { points, series,actions };

    } catch (error) {
        console.error("❌ API Fetch Error:", error);
        return { points: [], series: [] };
    }
};

