import * as React from "react";
import dayjs from "dayjs";
import utc from "dayjs/plugin/utc";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { DateTimePicker } from "@mui/x-date-pickers/DateTimePicker";
import { Grid, Box, Typography, TextField, Button, MenuItem, Select, List, ListItem, ListItemText, CircularProgress } from "@mui/material";
import { 
  TableContainer, 
  Table, 
  TableHead, 
  TableBody, 
  TableRow, 
  TableCell, 
  Paper 
} from "@mui/material";


import IncomeChart from "./Chart"
dayjs.extend(utc);

export default function SamplePage() {
  const [startDate, setStartDate] = React.useState(dayjs.utc());
  const [endDate, setEndDate] = React.useState(dayjs.utc());
  const [epochLength, setEpochLength] = React.useState("1 Day");
  const [numSurfers, setNumSurfers] = React.useState(0);
  const [numAnchors, setNumAnchors] = React.useState(0);
  const [analysisType, setAnalysisType] = React.useState("Pool Composition");

  const [chartData, setChartData] = React.useState(null); // Store data for the chart
  const [actions, setActions] = React.useState([]); // Store actions data
  const [loading, setLoading] = React.useState(false); // Loading state
// Determine the maximum number of rows (longest column)
  const maxRows = Math.max(...actions.map((col) => col.data.length));
  const handleSimulate = () => {
    const epochMapping = {
      "1 Day": 24 * 60 * 60 , // 1 day in ms
      "1 Week": 7 * 24 * 60 * 60 , // 7 days in ms
      "2 Weeks": 14 * 24 * 60 * 60 , // 14 days in ms
      "1 Month": 30 * 24 * 60 * 60 , // 30 days in ms
    };
  
    const epochValue = epochMapping[epochLength] || 604800; // Default to 1 day if not found
    // Set the state that will be passed to IncomeChart
    setChartData({
      startDate,
      endDate,
      epochLength: epochValue, // Send as timestamp (number),
      numSurfers,
      numAnchors,
      analysisType,
    });
  };

  const handleActionsUpdate = (newActions) => {
    setActions(newActions);
  };

  return (
    <LocalizationProvider dateAdapter={AdapterDayjs}>
      <Box sx={{ width: "100%", p: 2 }}>
        <Box 
          sx={{ 
            display: "flex", 
            alignItems: "center", 
            gap: 2, 
            flexWrap: "wrap"
          }}
        >
          {/* Start Date */}
          <DateTimePicker
            label="Select Start Date"
            value={startDate}
            onChange={(newValue) => setStartDate(dayjs.utc(newValue))}
            renderInput={(params) => <TextField {...params} />}
          />

          {/* End Date */}
          <DateTimePicker
            label="Select End Date"
            value={endDate}
            onChange={(newValue) => setEndDate(dayjs.utc(newValue))}
            renderInput={(params) => <TextField {...params} />}
          />

          {/* Epoch Length Dropdown */}
          <TextField
            select
            label="Epoch Length"
            value={epochLength}
            onChange={(e) => setEpochLength(e.target.value)}
          >
            {["1 Day", "1 Week", "2 Weeks", "1 Month"].map((option) => (
              <MenuItem key={option} value={option}>
                {option}
              </MenuItem>
            ))}
          </TextField>

          {/* Number of Surfers */}
          <TextField
            type="number"
            label="Surfers"
            value={numSurfers}
            onChange={(e) => setNumSurfers(e.target.value)}
          />

          {/* Number of Anchors */}
          <TextField
            type="number"
            label="Anchors"
            value={numAnchors}
            onChange={(e) => setNumAnchors(e.target.value)}
          />

          {/* Analysis Type Dropdown */}
          <TextField
            select
            label="Chart Option"
            value={analysisType}
            onChange={(e) => setAnalysisType(e.target.value)}
          >
            {["Pool Composition", "Compare", "Surfer Token Price", "Surfer vs Anchor", "Profits and Losses"].map((option) => (
              <MenuItem key={option} value={option}>
                {option}
              </MenuItem>
            ))}
          </TextField>

          {/* Simulate Button */}
          <Button
            variant="contained"
            color="primary"
            sx={{ height: "36px", fontSize: "14px", fontWeight: "bold", px: 2 }}
            onClick={handleSimulate}
          >
            Simulate
          </Button>
        </Box>
      </Box>

      {/* Chart Section */}
      <Box sx={{ width: "100%", p: 2 }}>
        <Typography variant="h5" sx={{ mb: 2 }}>
          {analysisType}
        </Typography>
        {chartData && <IncomeChart chartData={chartData} onActionsUpdate={handleActionsUpdate} />}
      </Box>

        {/* Actions List Section */}
<Box sx={{ width: "100%", p: 2 }}>
  <Typography variant="h6" sx={{ mt: 3, mb: 2 }}>
    Actions List
  </Typography>
              {console.log("actions is sample page :::: " ,actions)}
              {/* {console.log(actions[0], actions[1])} */}
  {loading ? (
    <CircularProgress />
  ) : actions.length > 0 ? (
    <TableContainer component={Paper} sx={{ mt: 2 }}>
    <Table>
      {/* Table Head */}
      <TableHead>
        <TableRow>
          {actions.map((col, index) => (
            <TableCell key={index} sx={{ fontWeight: "bold" }}>
              {col.name.toUpperCase()}
            </TableCell>
          ))}
        </TableRow>
      </TableHead>

      {/* Table Body */}
      <TableBody>
        {Array.from({ length: maxRows }).map((_, rowIndex) => (
          <TableRow key={rowIndex}>
            {actions.map((col, colIndex) => (
              <TableCell key={colIndex}>
                {col.data[rowIndex] !== undefined ? col.data[rowIndex] : "-"}
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  </TableContainer>
  ) : (
    <Typography>No actions available</Typography>
  )}
</Box>
    </LocalizationProvider>

  );
}

